import React, { useState } from 'react';

const UserInfoTab = ({ userInfo }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    ...userInfo,
    password: '',
    confirmPassword: '',
  }); 

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleCheckEmailDuplication = async () => {
    console.log(`이메일 중복 확인 요청: ${formData.email}`);
    
    if (formData.email === userInfo.email) {
      alert('현재 사용 중인 이메일이야! 변경하려면 다른 이메일을 입력해줘. 😉');
      return;
    }

    try {
      // 실제 API 호출 부분 (예시)
      // const response = await fetch('/api/check-email-duplication', {
      //   method: 'POST',
      //   headers: { 'Content-Type': 'application/json' },
      //   body: JSON.stringify({ email: formData.email }),
      // });
      // const data = await response.json();

      // if (data.isDuplicated) { 
      //   alert('🚨 이미 사용 중인 이메일입니다! 다른 이메일을 사용해줘. 😢');
      // } else {
      //   alert('✅ 사용 가능한 이메일입니다! 👍');
      // }

      // 가상 응답 (테스트용)
      const isDuplicated = formData.email === 'test@example.com';
      if (isDuplicated) {
        alert('🚨 이미 사용 중인 이메일입니다! 다른 이메일을 사용해줘. 😢');
      } else {
        alert('✅ 사용 가능한 이메일입니다! 👍');
      }

    } catch (error) {
      console.error('이메일 중복 확인 중 오류 발생:', error);
      alert('이메일 중복 확인 중 오류가 발생했어. 다시 시도해줘. 😥');
    }
  };

  const handleCheckNicknameDuplication = async () => {
    console.log(`닉네임 중복 확인 요청: ${formData.nickname}`);

    if (formData.nickname === userInfo.nickname) {
      alert('현재 사용 중인 닉네임이야! 변경하려면 다른 닉네임을 입력해줘. 😉');
      return;
    }

    try {
      // 실제 API 호출 부분 (예시)
      // const response = await fetch('/api/check-nickname-duplication', {
      //   method: 'POST',
      //   headers: { 'Content-Type': 'application/json' },
      //   body: JSON.stringify({ nickname: formData.nickname }),
      // });
      // const data = await response.json();

      // if (data.isDuplicated) { 
      //   alert('🚨 이미 사용 중인 닉네임입니다! 다른 닉네임을 사용해줘. 😢');
      // } else {
      //   alert('✅ 사용 가능한 닉네임입니다! 👍');
      // }

      // 가상 응답 (테스트용)
      const isDuplicated = formData.nickname === '중복닉네임';
      if (isDuplicated) {
        alert('🚨 이미 사용 중인 닉네임입니다! 다른 닉네임을 사용해줘. 😢');
      } else {
        alert('✅ 사용 가능한 닉네임입니다! 👍');
      }

    } catch (error) {
      console.error('닉네임 중복 확인 중 오류 발생:', error);
      alert('닉네임 중복 확인 중 오류가 발생했어. 다시 시도해줘. 😥');
    }
  };


  const handleSubmit = (e) => {
    e.preventDefault();

    if (formData.password || formData.confirmPassword) { 
      if (formData.password !== formData.confirmPassword) {
        alert('비밀번호와 비밀번호 확인이 일치하지 않아! 다시 확인해줘. 🧐');
        return;
      }
    }

    alert('회원 정보가 성공적으로 수정되었어! 🎉 (API 연동 필요)');
    console.log('수정된 정보:', formData);
    setIsEditing(false); 
  };

  const handleWithdrawal = () => {
    if (window.confirm('🚨 정말로 회원 탈퇴하시겠습니까? 모든 정보가 영구적으로 삭제돼! 😱')) {
      alert('회원 탈퇴가 완료되었어. 그동안 이용해줘서 고마워! 👋 (API 연동 필요)');
    }
  };

  return (
    <div className="tab-content-section user-info-tab">
      <h3 className="tab-content-title">회원 정보 {!isEditing ? '보기' : '수정'}</h3>

      {!isEditing ? (
        <>
          <div className="info-item">
            <span className="info-label">아이디</span>
            <span className="info-value">{userInfo.userId || '정보 없음'}</span> 
          </div>
          <div className="info-item">
            <span className="info-label">이메일</span>
            <span className="info-value">{userInfo.email || '정보 없음'}</span>
          </div>
          <div className="info-item">
            <span className="info-label">닉네임</span>
            <span className="info-value">{userInfo.nickname || '정보 없음'}</span> 
          </div>
          <div className="info-item">
            <span className="info-label">가입일</span>
            <span className="info-value">{userInfo.registeredDate || '정보 없음'}</span>
          </div>
          <button className="action-button" onClick={() => setIsEditing(true)}>정보 수정 ✏️</button>
        </>
      ) : (
        <form onSubmit={handleSubmit}>
          {/* 이메일 수정 필드 */}
          <div className="info-item action-input-group">
            <label className="info-label" htmlFor="email">이메일</label>
            <div className="input-with-button">
              <input
                type="email"
                id="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                className="info-value-input"
                required 
              />
              <button type="button" className="check-button" onClick={handleCheckEmailDuplication}>중복 확인</button>
            </div>
          </div>
          
          {/* 닉네임 수정 필드 */}
          <div className="info-item action-input-group">
            <label className="info-label" htmlFor="nickname">닉네임</label>
            <div className="input-with-button">
              <input
                type="text"
                id="nickname"
                name="nickname"
                value={formData.nickname}
                onChange={handleChange}
                className="info-value-input"
                required 
              />
              <button type="button" className="check-button" onClick={handleCheckNicknameDuplication}>중복 확인</button>
            </div>
          </div>

          {/* 비밀번호 변경 필드 - 이제 input-with-button을 사용해서 왼쪽 정렬 */}
          <div className="info-item action-input-group"> {/* 동일한 스타일 적용을 위해 클래스 추가 */}
            <label className="info-label" htmlFor="password">새 비밀번호</label>
            <div className="input-with-button"> {/* 이메일/닉네임처럼 input과 버튼을 묶는 구조 */}
              <input
                type="password"
                id="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                className="info-value-input"
                placeholder="변경할 비밀번호를 입력해줘"
                autoComplete="new-password" 
              />
              {/* 비밀번호는 별도 중복확인 버튼이 없으므로, 여기에 버튼 추가 안 함 */}
            </div>
          </div>
          <div className="info-item action-input-group"> {/* 동일한 스타일 적용을 위해 클래스 추가 */}
            <label className="info-label" htmlFor="confirmPassword">새 비밀번호 확인</label>
            <div className="input-with-button"> {/* 동일한 구조 적용 */}
              <input
                type="password"
                id="confirmPassword"
                name="confirmPassword"
                value={formData.confirmPassword}
                onChange={handleChange}
                className="info-value-input"
                placeholder="비밀번호를 다시 입력해줘"
                autoComplete="new-password" 
              />
            </div>
          </div>
          
          <div className="button-group" style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '30px' }}>
            <button type="submit" className="action-button">저장 ✅</button>
            <button type="button" className="action-button" onClick={() => setIsEditing(false)}>취소 ↩️</button>
            <button type="button" className="action-button delete-button" onClick={handleWithdrawal}>회원 탈퇴 🗑️</button>
          </div>
        </form>
      )}
    </div>
  );
};

export default UserInfoTab;
